using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using MyExpenseTracker.Api.Data;using MyExpenseTracker.Api.Models;namespace MyExpenseTracker.Api.Controllers;[Authorize,ApiController,Route("api/accounts")]public class AccountsController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult> Get()=>Ok(await db.Accounts.OrderBy(x=>x.Name).ToListAsync());[HttpPost]public async Task<IActionResult> Add(Account x){if(string.IsNullOrWhiteSpace(x.Name)||x.OpeningBalance<0)return BadRequest();x.Id=0;x.Name=x.Name.Trim();db.Accounts.Add(x);await db.SaveChangesAsync();return Ok(x);}[HttpPut("{id:int}")]public async Task<IActionResult> Edit(int id,Account x){var a=await db.Accounts.FindAsync(id);if(a==null)return NotFound();if(string.IsNullOrWhiteSpace(x.Name)||x.OpeningBalance<0)return BadRequest();a.Name=x.Name.Trim();a.OpeningBalance=x.OpeningBalance;a.Type=x.Type;await db.SaveChangesAsync();return Ok(a);}}